#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include "../test_framework.h"
#include "../../src/lexer.h"
#include "../../src/parser.h"
#include "../../src/ir.h"
#include "../../src/sema.h"
#include "../../src/codegen.h"

/* Helper: compile C code to assembly */
int compile_c_to_asm(const char *code, const char *out_file) {
    Lexer *lex = lexer_new(code, strlen(code));
    if (!lex) return -1;

    if (lexer_tokenize(lex) != 0) {
        lexer_free(lex);
        return -1;
    }

    Parser *p = parser_new(lex);
    if (!p) {
        lexer_free(lex);
        return -1;
    }

    Node *program = parse_program(p);
    parser_free(p);
    lexer_free(lex);

    if (!program) return -1;

    /* Semantic analysis */
    Sema *sema = sema_new();
    if (!sema) {
        node_free_recursive(program);
        return -1;
    }

    sema_check(sema, program);
    sema_free(sema);

    /* CIR generation */
    CirModule *module = cir_module_new();
    if (!module) {
        node_free_recursive(program);
        return -1;
    }

    astgen_program(module, program);
    node_free_recursive(program);

    /* Code generation */
    FILE *out = fopen(out_file, "w");
    if (!out) {
        cir_module_free(module);
        return -1;
    }

    Codegen *cg = codegen_new(module, out);
    if (!cg) {
        fclose(out);
        cir_module_free(module);
        return -1;
    }

    codegen_emit(cg);
    codegen_free(cg);
    fclose(out);
    cir_module_free(module);

    return 0;
}

/* Helper: check if assembly file contains a pattern */
int asm_contains(const char *asm_file, const char *pattern) {
    FILE *f = fopen(asm_file, "r");
    if (!f) return 0;

    char line[512];
    int found = 0;
    while (fgets(line, sizeof(line), f)) {
        if (strstr(line, pattern)) {
            found = 1;
            break;
        }
    }

    fclose(f);
    return found;
}

/* Helper: compile assembly with gcc */
int compile_asm_with_gcc(const char *asm_file, const char *exe_file) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "gcc %s -o %s 2>&1", asm_file, exe_file);
    return system(cmd) == 0 ? 0 : -1;
}

/* ============ Function Prologue/Epilogue Tests ============ */

TEST(test_codegen_func_prologue) {
    ASSERT(compile_c_to_asm("void f() { }", "/tmp/test_prologue.s") == 0);
    ASSERT(asm_contains("/tmp/test_prologue.s", "pushq\t%rbp"));
    ASSERT(asm_contains("/tmp/test_prologue.s", "movq\t%rsp, %rbp"));
}

TEST(test_codegen_func_epilogue) {
    ASSERT(compile_c_to_asm("void f() { }", "/tmp/test_epilogue.s") == 0);
    ASSERT(asm_contains("/tmp/test_epilogue.s", "popq\t%rbp"));
    ASSERT(asm_contains("/tmp/test_epilogue.s", "ret"));
}

TEST(test_codegen_func_int_return) {
    ASSERT(compile_c_to_asm("int f() { return 42; }", "/tmp/test_ret_int.s") == 0);
    ASSERT(asm_contains("/tmp/test_ret_int.s", "movq\t$42"));
    ASSERT(asm_contains("/tmp/test_ret_int.s", "ret"));
}

/* ============ Literal Load Tests ============ */

TEST(test_codegen_load_int_literal) {
    ASSERT(compile_c_to_asm("int f() { int x = 10; return x; }", "/tmp/test_load_int.s") == 0);
    ASSERT(asm_contains("/tmp/test_load_int.s", "movq\t$10"));
}

TEST(test_codegen_load_float_literal) {
    ASSERT(compile_c_to_asm("float f() { float x = 3.14; return x; }", "/tmp/test_load_float.s") == 0);
    /* Check that assembly is generated (float handling varies) */
    FILE *f = fopen("/tmp/test_load_float.s", "r");
    ASSERT(f != NULL);
    fclose(f);
}

TEST(test_codegen_load_string_literal) {
    ASSERT(compile_c_to_asm("char* f() { return \"hello\"; }", "/tmp/test_load_str.s") == 0);
    ASSERT(asm_contains("/tmp/test_load_str.s", ".LC0"));
    ASSERT(asm_contains("/tmp/test_load_str.s", ".string"));
}

TEST(test_codegen_load_variable) {
    ASSERT(compile_c_to_asm("int f() { int x; x = 5; return x; }", "/tmp/test_load_var.s") == 0);
    FILE *f = fopen("/tmp/test_load_var.s", "r");
    ASSERT(f != NULL);
    fclose(f);
}

/* ============ Arithmetic Operation Tests ============ */

TEST(test_codegen_add_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 5; int y = 3; return x + y; }", "/tmp/test_add.s") == 0);
    ASSERT(asm_contains("/tmp/test_add.s", "addq"));
}

TEST(test_codegen_sub_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 10; int y = 3; return x - y; }", "/tmp/test_sub.s") == 0);
    ASSERT(asm_contains("/tmp/test_sub.s", "subq"));
}

TEST(test_codegen_mul_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 4; int y = 5; return x * y; }", "/tmp/test_mul.s") == 0);
    ASSERT(asm_contains("/tmp/test_mul.s", "imulq"));
}

TEST(test_codegen_div_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 20; int y = 4; return x / y; }", "/tmp/test_div.s") == 0);
    ASSERT(asm_contains("/tmp/test_div.s", "idivq"));
}

TEST(test_codegen_mod_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 10; int y = 3; return x % y; }", "/tmp/test_mod.s") == 0);
    ASSERT(asm_contains("/tmp/test_mod.s", "idivq"));
}

/* ============ Comparison Operation Tests ============ */

TEST(test_codegen_eq_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 5; int y = 5; return x == y; }", "/tmp/test_eq.s") == 0);
    ASSERT(asm_contains("/tmp/test_eq.s", "cmpq"));
    ASSERT(asm_contains("/tmp/test_eq.s", "sete"));
}

TEST(test_codegen_neq_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 5; int y = 3; return x != y; }", "/tmp/test_neq.s") == 0);
    ASSERT(asm_contains("/tmp/test_neq.s", "cmpq"));
    ASSERT(asm_contains("/tmp/test_neq.s", "setne"));
}

TEST(test_codegen_lt_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 3; int y = 5; return x < y; }", "/tmp/test_lt.s") == 0);
    ASSERT(asm_contains("/tmp/test_lt.s", "cmpq"));
    ASSERT(asm_contains("/tmp/test_lt.s", "setl"));
}

TEST(test_codegen_gt_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 5; int y = 3; return x > y; }", "/tmp/test_gt.s") == 0);
    ASSERT(asm_contains("/tmp/test_gt.s", "cmpq"));
    ASSERT(asm_contains("/tmp/test_gt.s", "setg"));
}

/* ============ Unary Operation Tests ============ */

TEST(test_codegen_neg_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 5; return -x; }", "/tmp/test_neg.s") == 0);
    ASSERT(asm_contains("/tmp/test_neg.s", "negq"));
}

TEST(test_codegen_not_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 0; return !x; }", "/tmp/test_not.s") == 0);
    ASSERT(asm_contains("/tmp/test_not.s", "cmpq"));
    ASSERT(asm_contains("/tmp/test_not.s", "sete"));
}

TEST(test_codegen_bitnot_operation) {
    ASSERT(compile_c_to_asm("int f() { int x = 5; return ~x; }", "/tmp/test_bitnot.s") == 0);
    ASSERT(asm_contains("/tmp/test_bitnot.s", "notq"));
}

/* ============ Control Flow Tests ============ */

TEST(test_codegen_label) {
    ASSERT(compile_c_to_asm("void f() { while (1) { break; } }", "/tmp/test_label.s") == 0);
    ASSERT(asm_contains("/tmp/test_label.s", ".L"));
}

TEST(test_codegen_jmp) {
    ASSERT(compile_c_to_asm("void f() { while (1) { break; } }", "/tmp/test_jmp.s") == 0);
    ASSERT(asm_contains("/tmp/test_jmp.s", "jmp"));
}

TEST(test_codegen_jmp_if) {
    ASSERT(compile_c_to_asm("void f() { int x; if (x) { } }", "/tmp/test_jmp_if.s") == 0);
    ASSERT(asm_contains("/tmp/test_jmp_if.s", "je") || asm_contains("/tmp/test_jmp_if.s", "jne"));
}

TEST(test_codegen_if_stmt) {
    ASSERT(compile_c_to_asm("void f() { int x; if (x) { x = 1; } }", "/tmp/test_if.s") == 0);
    FILE *f = fopen("/tmp/test_if.s", "r");
    ASSERT(f != NULL);
    fclose(f);
}

TEST(test_codegen_while_stmt) {
    ASSERT(compile_c_to_asm("void f() { int x = 0; while (x < 10) { x = x + 1; } }", "/tmp/test_while.s") == 0);
    FILE *f = fopen("/tmp/test_while.s", "r");
    ASSERT(f != NULL);
    fclose(f);
}

/* ============ Function Call Tests ============ */

TEST(test_codegen_func_call_no_args) {
    ASSERT(compile_c_to_asm("int g() { return 42; } void f() { g(); }", "/tmp/test_call_noargs.s") == 0);
    ASSERT(asm_contains("/tmp/test_call_noargs.s", "call"));
}

TEST(test_codegen_func_call_one_arg) {
    ASSERT(compile_c_to_asm("int g(int x) { return x; } void f() { g(5); }", "/tmp/test_call_onearg.s") == 0);
    ASSERT(asm_contains("/tmp/test_call_onearg.s", "call"));
    ASSERT(asm_contains("/tmp/test_call_onearg.s", "%rdi"));
}

TEST(test_codegen_func_call_two_args) {
    ASSERT(compile_c_to_asm("int g(int a, int b) { return a + b; } void f() { g(1, 2); }", "/tmp/test_call_twoargs.s") == 0);
    ASSERT(asm_contains("/tmp/test_call_twoargs.s", "call"));
    ASSERT(asm_contains("/tmp/test_call_twoargs.s", "%rdi"));
    ASSERT(asm_contains("/tmp/test_call_twoargs.s", "%rsi"));
}

TEST(test_codegen_func_call_return_value) {
    ASSERT(compile_c_to_asm("int g(int x) { return x; } int f() { return g(42); }", "/tmp/test_call_ret.s") == 0);
    FILE *f = fopen("/tmp/test_call_ret.s", "r");
    ASSERT(f != NULL);
    fclose(f);
}

/* ============ Assembly Link Tests ============ */

TEST(test_codegen_assembly_links_simple) {
    ASSERT(compile_c_to_asm("int main() { return 0; }", "/tmp/test_link_main.s") == 0);
    ASSERT(compile_asm_with_gcc("/tmp/test_link_main.s", "/tmp/test_link_main") == 0);
}

TEST(test_codegen_assembly_links_with_func) {
    ASSERT(compile_c_to_asm("int add(int a, int b) { return a + b; } int main() { return add(1, 2); }", "/tmp/test_link_func.s") == 0);
    ASSERT(compile_asm_with_gcc("/tmp/test_link_func.s", "/tmp/test_link_func") == 0);
}

/* ============ Rodata Section Tests ============ */

TEST(test_codegen_rodata_section) {
    ASSERT(compile_c_to_asm("char* f() { return \"test\"; }", "/tmp/test_rodata.s") == 0);
    ASSERT(asm_contains("/tmp/test_rodata.s", ".rodata") || asm_contains("/tmp/test_rodata.s", ".section"));
}

TEST(test_codegen_multiple_strings) {
    ASSERT(compile_c_to_asm("char* f() { return \"hello\"; } char* g() { return \"world\"; }", "/tmp/test_multi_str.s") == 0);
    ASSERT(asm_contains("/tmp/test_multi_str.s", ".LC0"));
}

/* Main test runner */
int main(void) {
    printf("=== Test Suite: Codegen Tests ===\n\n");

    /* Function Prologue/Epilogue */
    RUN_TEST(test_codegen_func_prologue);
    RUN_TEST(test_codegen_func_epilogue);
    RUN_TEST(test_codegen_func_int_return);

    /* Literal Loads */
    RUN_TEST(test_codegen_load_int_literal);
    RUN_TEST(test_codegen_load_float_literal);
    RUN_TEST(test_codegen_load_string_literal);
    RUN_TEST(test_codegen_load_variable);

    /* Arithmetic Operations */
    RUN_TEST(test_codegen_add_operation);
    RUN_TEST(test_codegen_sub_operation);
    RUN_TEST(test_codegen_mul_operation);
    RUN_TEST(test_codegen_div_operation);
    RUN_TEST(test_codegen_mod_operation);

    /* Comparison Operations */
    RUN_TEST(test_codegen_eq_operation);
    RUN_TEST(test_codegen_neq_operation);
    RUN_TEST(test_codegen_lt_operation);
    RUN_TEST(test_codegen_gt_operation);

    /* Unary Operations */
    RUN_TEST(test_codegen_neg_operation);
    RUN_TEST(test_codegen_not_operation);
    RUN_TEST(test_codegen_bitnot_operation);

    /* Control Flow */
    RUN_TEST(test_codegen_label);
    RUN_TEST(test_codegen_jmp);
    RUN_TEST(test_codegen_jmp_if);
    RUN_TEST(test_codegen_if_stmt);
    RUN_TEST(test_codegen_while_stmt);

    /* Function Calls */
    RUN_TEST(test_codegen_func_call_no_args);
    RUN_TEST(test_codegen_func_call_one_arg);
    RUN_TEST(test_codegen_func_call_two_args);
    RUN_TEST(test_codegen_func_call_return_value);

    /* Assembly Link */
    RUN_TEST(test_codegen_assembly_links_simple);
    RUN_TEST(test_codegen_assembly_links_with_func);

    /* Rodata Section */
    RUN_TEST(test_codegen_rodata_section);
    RUN_TEST(test_codegen_multiple_strings);

    printf("\n=== Results ===\n");
    printf("Total:   %d\n", g_test_count);
    printf("Passed:  %d ✓\n", g_test_passed);
    printf("Failed:  %d ✗\n", g_test_count - g_test_passed);

    return (g_test_count - g_test_passed) > 0 ? 1 : 0;
}

