#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>

/* 우리 컴파일러 헤더 포함 */
#include "/tmp/c-compiler-project/src/lexer.h"
#include "/tmp/c-compiler-project/src/parser.h"
#include "/tmp/c-compiler-project/src/ir.h"
#include "/tmp/c-compiler-project/src/sema.h"
#include "/tmp/c-compiler-project/src/codegen.h"

int compile_file(const char *input_file, const char *output_file) {
    /* 파일 읽기 */
    FILE *f = fopen(input_file, "r");
    if (!f) {
        fprintf(stderr, "ERROR: 파일 열기 실패: %s\n", input_file);
        return -1;
    }

    struct stat st;
    stat(input_file, &st);
    size_t size = st.st_size;
    char *code = malloc(size + 1);
    if (!code) {
        fclose(f);
        return -1;
    }

    if (fread(code, 1, size, f) != size) {
        fprintf(stderr, "ERROR: 파일 읽기 실패\n");
        free(code);
        fclose(f);
        return -1;
    }
    code[size] = '\0';
    fclose(f);

    printf("✓ %s 읽기 완료 (%zu bytes)\n", input_file, size);

    /* Lexer */
    Lexer *lex = lexer_new(code, size);
    if (!lex || lexer_tokenize(lex) != 0) {
        fprintf(stderr, "ERROR: Lexer 실패\n");
        free(code);
        return -1;
    }
    printf("✓ Lexer 통과\n");

    /* Parser */
    Parser *p = parser_new(lex);
    Node *program = parse_program(p);
    parser_free(p);
    lexer_free(lex);

    if (!program) {
        fprintf(stderr, "ERROR: Parser 실패\n");
        free(code);
        return -1;
    }
    printf("✓ Parser 통과\n");

    /* Semantic Analysis */
    Sema *sema = sema_new();
    sema_check(sema, program);
    if (sema->error_count > 0) {
        fprintf(stderr, "ERROR: Semantic Analysis 실패 (에러 %d개)\n", sema->error_count);
        sema_free(sema);
        node_free_recursive(program);
        free(code);
        return -1;
    }
    sema_free(sema);
    printf("✓ Semantic Analysis 통과\n");

    /* CIR 생성 */
    CirModule *module = cir_module_new();
    AstGen *gen = astgen_new(module);
    astgen_program(gen, program);
    astgen_free(gen);
    node_free_recursive(program);
    printf("✓ CIR 생성 완료\n");

    /* Code Generation */
    FILE *out = fopen(output_file, "w");
    if (!out) {
        fprintf(stderr, "ERROR: 출력 파일 열기 실패: %s\n", output_file);
        cir_module_free(module);
        free(code);
        return -1;
    }

    Codegen *cg = codegen_new(module, out);
    codegen_emit(cg);
    codegen_free(cg);
    fclose(out);
    cir_module_free(module);

    printf("✓ 어셈블리 생성 완료: %s\n", output_file);
    free(code);
    return 0;
}

int main() {
    printf("=== C 컴파일러 예제 테스트 ===\n\n");

    /* 예제 1: 함수 호출 */
    printf("[예제 1] 두 수의 합\n");
    if (compile_file("/tmp/example1_add.c", "/tmp/example1_add.s") == 0) {
        printf("✓ 예제 1 컴파일 성공\n\n");
    } else {
        printf("✗ 예제 1 컴파일 실패\n\n");
    }

    /* 예제 2: 반복문 */
    printf("[예제 2] 팩토리얼 (반복문)\n");
    if (compile_file("/tmp/example2_factorial.c", "/tmp/example2_factorial.s") == 0) {
        printf("✓ 예제 2 컴파일 성공\n\n");
    } else {
        printf("✗ 예제 2 컴파일 실패\n\n");
    }

    /* 예제 3: 조건문 */
    printf("[예제 3] 절댓값 (조건문)\n");
    if (compile_file("/tmp/example3_abs.c", "/tmp/example3_abs.s") == 0) {
        printf("✓ 예제 3 컴파일 성공\n\n");
    } else {
        printf("✗ 예제 3 컴파일 실패\n\n");
    }

    return 0;
}
EOF
