#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "/tmp/c-compiler-project/src/lexer.h"
#include "/tmp/c-compiler-project/src/parser.h"
#include "/tmp/c-compiler-project/src/ir.h"
#include "/tmp/c-compiler-project/src/sema.h"
#include "/tmp/c-compiler-project/src/codegen.h"

int compile_c_to_asm(const char *code, const char *out_file) {
    Lexer *lex = lexer_new(code, strlen(code));
    if (!lex) return -1;

    if (lexer_tokenize(lex) != 0) {
        lexer_free(lex);
        return -1;
    }

    Parser *p = parser_new(lex);
    if (!p) {
        lexer_free(lex);
        return -1;
    }

    Node *program = parse_program(p);
    parser_free(p);
    lexer_free(lex);

    if (!program) return -1;

    Sema *sema = sema_new();
    if (!sema) {
        node_free_recursive(program);
        return -1;
    }

    sema_check(sema, program);
    int sema_errors = sema->error_count;
    sema_free(sema);

    if (sema_errors > 0) {
        node_free_recursive(program);
        return -1;
    }

    CirModule *module = cir_module_new();
    if (!module) {
        node_free_recursive(program);
        return -1;
    }

    AstGen *gen = astgen_new(module);
    if (!gen) {
        cir_module_free(module);
        node_free_recursive(program);
        return -1;
    }

    astgen_program(gen, program);
    astgen_free(gen);
    node_free_recursive(program);

    FILE *out = fopen(out_file, "w");
    if (!out) {
        cir_module_free(module);
        return -1;
    }

    Codegen *cg = codegen_new(module, out);
    if (!cg) {
        fclose(out);
        cir_module_free(module);
        return -1;
    }

    codegen_emit(cg);
    codegen_free(cg);
    fclose(out);
    cir_module_free(module);

    return 0;
}

int main() {
    printf("=== C 컴파일러 예제 테스트 ===\n\n");

    /* 예제 1 */
    printf("[예제 1] 두 수의 합\n");
    const char *ex1 = "int add(int a, int b) { return a + b; } int main() { return add(10, 20); }";
    if (compile_c_to_asm(ex1, "/tmp/ex1.s") == 0) {
        printf("✓ 컴파일 성공: /tmp/ex1.s\n");
    } else {
        printf("✗ 컴파일 실패\n");
    }

    /* 예제 2 */
    printf("\n[예제 2] 팩토리얼 (반복문)\n");
    const char *ex2 = "int factorial(int n) { int r = 1; int i = 1; while (i <= n) { r = r * i; i = i + 1; } return r; } int main() { return factorial(5); }";
    if (compile_c_to_asm(ex2, "/tmp/ex2.s") == 0) {
        printf("✓ 컴파일 성공: /tmp/ex2.s\n");
    } else {
        printf("✗ 컴파일 실패\n");
    }

    /* 예제 3 */
    printf("\n[예제 3] 절댓값 (조건문)\n");
    const char *ex3 = "int abs_value(int x) { if (x < 0) { return -x; } return x; } int main() { return abs_value(-42); }";
    if (compile_c_to_asm(ex3, "/tmp/ex3.s") == 0) {
        printf("✓ 컴파일 성공: /tmp/ex3.s\n");
    } else {
        printf("✗ 컴파일 실패\n");
    }

    printf("\n=== 어셈블리 파일 생성 완료 ===\n");
    return 0;
}
EOF

